/// Anything else would change the installer URL or reach `install.sh` raw.
final RegExp _versionPattern = RegExp(r'^v?\d+\.\d+\.\d+(-[0-9A-Za-z.-]+)?$');

/// Upgrade runner. All side effects are injectable for tests.
